DROP TABLE IF EXISTS `competitionResults`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `competitionResults` (
  `season` int NOT NULL,
  `competitionId` int NOT NULL,
  `athleteId` int NOT NULL,
  `finished` int NOT NULL,
  `points` double NOT NULL,
  PRIMARY KEY (`competitionId`,`season`,`athleteId`),
  KEY `athleteId` (`athleteId`),
  CONSTRAINT `competitionResults_ibfk_1` FOREIGN KEY (`competitionId`, `season`) REFERENCES `competitions` (`competitionId`, `season`) ON DELETE CASCADE,
